package com.finsight.domain; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class CreditApplication { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(optional=false) Customer customer; Double requestedAmount; Integer tenureMonths; @Enumerated(EnumType.STRING) ApplicationStatus status=ApplicationStatus.SUBMITTED; Integer riskScore; String riskLevel,decisionReason; LocalDateTime createdAt=LocalDateTime.now(),updatedAt=LocalDateTime.now(); public Long getId(){return id;} public Customer getCustomer(){return customer;} public Double getRequestedAmount(){return requestedAmount;} public Integer getTenureMonths(){return tenureMonths;} public ApplicationStatus getStatus(){return status;} public Integer getRiskScore(){return riskScore;} public String getRiskLevel(){return riskLevel;} public String getDecisionReason(){return decisionReason;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCustomer(Customer v){customer=v;} public void setRequestedAmount(Double v){requestedAmount=v;} public void setTenureMonths(Integer v){tenureMonths=v;} public void setStatus(ApplicationStatus v){status=v;} public void setRiskScore(Integer v){riskScore=v;} public void setRiskLevel(String v){riskLevel=v;} public void setDecisionReason(String v){decisionReason=v;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
